"use strict";window.troyServerSort=(()=>{return{versions:function(a=[],b="ASC",c="version"){const d=/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/,e={dev:0,alpha:1,a:1,beta:2,b:2,rc:3,"#":4,pl:5,p:5,_unknown:6},f=a=>{const b=/^\d+\.\d+$/.test(a)?`${a}.0`:a,c=b.match(d);if(!c)return[0,0,0,0];const f=parseInt(c[1],10),g=parseInt(c[2],10),h=parseInt(c[3],10);let i=[];if(c[4]){const a=c[4].split(".");a.forEach(a=>{const b=a.match(/^[a-zA-Z]+/);if(b){const c=b[0].toLowerCase(),d=a.slice(c.length).replace(/^-+|-+$/g,"");i.push(e?.[c]||e._unknown),i.push(d?parseInt(d,10):0)}else i.push(-1)})}else i.push(7);const j=c[5]?.split(".").map(a=>parseInt(a,10))||[];return[f,g,h,...i,...j]},g="DESC"===b.toUpperCase()?-1:1;return a.sort((d,a)=>{const b=f(d[c]),e=f(a[c]);for(let c=0;c<Math.max(b.length,e.length);c++)if(b[c]!==e[c])return(b[c]-e[c])*g;return 0})}}})();
